create or replace view public.intimacoes_agrupadas with (security_invoker = true) as with base as (select i.id, i.raw_id, i.numero_processo, i.tipo_numeracao, i.tribunal_sigla, i.orgao_julgador, i.data_disponibilizacao, i.origem, i.observacoes, i.duplicado, i.repetida, i.acao_sugerida_ia, i.resumo_ia, i.prazo_extraido_texto, i.data_fatal_calculada, i.advogado_id, i.status_fluxo, i.distribuido_em, i.trecho_fundamentador, i.pendencias, i.status_analise, i.analisado_em, i.arquivado_em, count(*) over (partition by i.numero_processo_normalizado) as publicacoes, count(*) filter (where i.repetida) over (partition by i.numero_processo_normalizado) as repetidas, row_number() over (partition by i.numero_processo_normalizado order by i.data_disponibilizacao desc nulls last, i.created_at desc, i.id desc) as ordem_grupo from public.intimacoes i) select id, raw_id, numero_processo, tipo_numeracao, tribunal_sigla, orgao_julgador, data_disponibilizacao, origem, observacoes, duplicado, repetida, acao_sugerida_ia, resumo_ia, prazo_extraido_texto, data_fatal_calculada, advogado_id, status_fluxo, distribuido_em, trecho_fundamentador, pendencias, status_analise, analisado_em, arquivado_em, publicacoes, repetidas from base where ordem_grupo = 1